delta1 = [abs(v10[i]-rs[i]) for i in range(256)]
delta2 = [abs(v20[i]-rs[i]) for i in range(256)]
delta3 = [abs(fulltimepad_y[i]-rs[i]) for i in range(256)]

# Compute rolling confidence intervals
confidence = 0.95 # it's high since the values can change randomly
window_size = 3  # You can adjust this window size

mean_delta = []
lower_bound = []
upper_bound = []
graphx = [i for i in range(256)] # temp

for i in range(len(delta3)):
    start = max(0, i - window_size // 2)
    end = min(len(delta3), i + window_size // 2 + 1)
    window = delta3[start:end]
    mean = np.mean(window)
    std_err = stats.sem(window)  # Standard error
    ci = stats.t.interval(confidence, df=len(window)-1, loc=mean, scale=std_err)
    mean_delta.append(mean)
    lower_bound.append(ci[0])
    upper_bound.append(ci[1])


plt.figure(figsize=(8, 5))
